// Generated by devtoolbox. This binary verifies the project-to-broker path.

use std::{env, io, process, time::Duration};

use futures_lite::stream::StreamExt;
use lapin::{
    BasicProperties, Connection, ConnectionProperties,
    options::{BasicAckOptions, BasicConsumeOptions, BasicPublishOptions, QueueDeclareOptions},
    types::FieldTable,
};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let url = env::var("RABBITMQ_URL").map_err(|_| {
        io::Error::new(io::ErrorKind::NotFound, "RABBITMQ_URL est absente")
    })?;
    let connection = Connection::connect(
        &url,
        ConnectionProperties::default().with_connection_name("devtoolbox-check".into()),
    )
    .await?;
    let channel = connection.create_channel().await?;
    let queue_name = format!("devtoolbox.check.{}", process::id());
    channel
        .queue_declare(
            queue_name.clone().into(),
            QueueDeclareOptions {
                exclusive: true,
                auto_delete: true,
                ..QueueDeclareOptions::default()
            },
            FieldTable::default(),
        )
        .await?;
    let mut consumer = channel
        .basic_consume(
            queue_name.clone().into(),
            "devtoolbox-check".into(),
            BasicConsumeOptions::default(),
            FieldTable::default(),
        )
        .await?;
    let payload = b"devtoolbox-rabbitmq-roundtrip";
    channel
        .basic_publish(
            "".into(),
            queue_name.into(),
            BasicPublishOptions::default(),
            payload,
            BasicProperties::default(),
        )
        .await?
        .await?;

    let delivery = tokio::time::timeout(Duration::from_secs(10), consumer.next())
        .await?
        .ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "consumer interrompu"))??;
    if delivery.data != payload {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "payload AMQP altéré").into());
    }
    delivery.ack(BasicAckOptions::default()).await?;
    connection.close(200, "check complete".into()).await?;
    println!("aller-retour AMQP réussi (publication + consommation)");
    Ok(())
}
